Definition RF_FR : Z := 5600%Z.
Definition AEXIT : Z := 0x0ff2ac%Z.
Definition STOPSR : list Z := [0x104dfc; AEXIT]%Z.
Definition FUELR : nat := 20000.

(* [comment removed for export] *)
Definition rf_sr : list expr :=
  Eval cbv in (map (fun i => match i with
                          | 0 => ELit 0%Z | 2 => EVar 0
                          | _ => EVar (2 + i) end)%nat (seq 0 32)).

(* [comment removed for export] *)
Definition rf_cells : list (Z * nat * Z) :=
  [(0x11d210, 8%nat, 0x105c88);
   (0x11d340, 8%nat, 0x10d778);
   (0x11d348, 8%nat, 0x10db7c);
   (0x129478, 8%nat, 0x7fff8000);
   (0x12a158, 1%nat, 0x1);
   (0x12a159, 1%nat, 0x1);
   (0x1baffc, 1%nat, 0x1);
   (0x11fc30, 4%nat, 0x5);
   (0x11fc50, 8%nat, 0x0);
   (0x11fc58, 8%nat, 0x0);
   (0x11fc68, 8%nat, 0x0);
   (0x11fc78, 8%nat, 0x104dfc);
   (0x11fc88, 8%nat, 0x67dbb8);
   (0x11fc90, 8%nat, 0x0);
   (0x11fca8, 4%nat, 0x2);
   (0x11fcb8, 4%nat, 0x0);
   (0x11fcbc, 4%nat, 0xffffffff);
   (0x11fcc0, 4%nat, 0xffffffff);
   (0x7fffb6c8, 8%nat, 0x0);
   (0x7fffb6d0, 8%nat, 0x0)]%Z.

(* [comment removed for export] *)
Definition RF_OFFS : list Z := [-464; -451; -849; -856; -443; -450; -427; -442]%Z.

Definition rf_kn : list kentry :=
  [KAlign (EVar 0) 16; KRange (EVar 0) ASP_LO ASP_HI; KWr (SA (EVar 0) (- RF_FR)) RF_FR;
   KImg 0x10000 0x4d000; KImg 0x115000 0x11d000]%Z
  ++ shkn RF_OFFS
  ++ [KWord (SA (ELit 0) 0x67d4f0) 8 (EVar 1); KWr (SA (ELit 0) 0x11fc30) 232]%Z
  ++ kn_cells rf_cells.

(* [comment removed for export] *)
Definition rf_dirsA : list bool := [false; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; false; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; true; false; false; false; false; false; false; false; false; false; true; false; false].   (* [comment removed for export] *)
Definition scrR : scripts := SCR rf_dirsA [] [].

(* [comment removed for export] *)
Definition rf_rA := Eval vm_compute in (sym_exec RSEGS FUELR true STOPSR scrR (SS 0x0a2f18 rf_sr [] rf_kn 34) []).
Definition rf_cA := Eval vm_compute in (carry (s_log (fst (fst rf_rA))) rf_kn []).
Definition rf_srA : list expr := Eval vm_compute in (s_regs (fst (fst rf_rA))).
Definition rf_knA : list kentry := Eval vm_compute in (fst (fst rf_cA)).
Definition rf_scsA : list sidecond := Eval vm_compute in (snd (fst rf_rA)).
(* [comment removed for export] *)
Definition rf_sc : stdio_res := Eval vm_compute in
  (match stdio_call 34 rf_srA rf_knA with Some r => r
   | None => SCR_ 0 0 0 (ELit 0) (ELit 0) (ELit 0) (ELit 0) (ELit 0) (ELit 0) (ELit 0) [] [] end).
(* [comment removed for export] *)
Definition rf_rC := Eval vm_compute in (sym_exec RSEGS FUELR true STOPSR scr0 (SS (sc_ret rf_sc) (sc_sr rf_sc) [] (sc_kn rf_sc) 66) []).
Definition rf_cC := Eval vm_compute in (carry (s_log (fst (fst rf_rC))) (sc_kn rf_sc) []).
Definition rf_srF : list expr := Eval vm_compute in (s_regs (fst (fst rf_rC))).
Definition rf_knF : list kentry := Eval vm_compute in (fst (fst rf_cC)).

(* [comment removed for export] *)
Definition rf_msgZ : list Z := Eval vm_compute in (match kbytes rf_knA (EVar 0) (-464) 38 with Some l => l | None => [] end).

Lemma rf_itinerary :
  s_pc (fst (fst rf_rA)) = 0x104dfc%Z /\ snd (fst rf_rA) = rf_scsA /\ snd (fst rf_cA) = []
  /\ stdio_call 34 rf_srA rf_knA = Some rf_sc
  /\ (sc_ret rf_sc, sc_f rf_sc, sc_fd rf_sc, sc_s rf_sc, sc_l rf_sc, sc_wb rf_sc, sc_wp rf_sc)
     = (0x105db0%Z, 0x11fc30%Z, 2%Z, ELit 0%Z, ELit 0%Z, EAlu ALU_ADD (EVar 0) (ELit (-464)%Z), EAlu ALU_ADD (EVar 0) (ELit (-426)%Z))
  /\ kbytes rf_knA (EVar 0) (-464) 38 = Some rf_msgZ /\ zbytes rf_msgZ = msg_refused
  /\ s_pc (fst (fst rf_rC)) = AEXIT /\ snd (fst rf_rC) = [] /\ snd (fst rf_cC) = [].
